	public InsertionOrder getInsertionOrder( InsertionOrderFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "InsertionOrderFetchOneSummary arg cannot be null" );

		InsertionOrder entity = null;
		UUID id = summary.getInsertionOrderId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a InsertionOrder using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


